1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
thunderbolt: Clamp XDomain response data copy to allocation
 size

tb_xdp_properties_request() derives the per-packet copy length from
the response header without checking that it fits in the previously
allocated data buffer.  A malicious peer can set its length field
larger than the declared data_length, causing memcpy to write past
the kcalloc allocation.

Clamp the per-packet copy length so that the cumulative offset
never exceeds data_len.

Fixes: cdae7c07e3e3 ("thunderbolt: Add support for XDomain properties")
Cc: stable@vger.kernel.org
Assisted-by: Claude:claude-opus-4-7
Signed-off-by: Michael Bommarito <michael.bommarito@gmail.com>
Signed-off-by: Mika Westerberg <mika.westerberg@linux.intel.com>

Here is the root cause:
The function tb_xdp_properties_request() derives the per-packet copy length `len` from the response header without validating that it does not exceed the remaining space in the pre-allocated `data` buffer. A malicious XDomain peer can set the length field larger than the declared `data_len`, causing `memcpy` to write past the allocated buffer (heap buffer overflow).

Here is the patch:

 static int tb_xdp_properties_request(struct tb_ctl *ctl, u64 route,
 	const uuid_t *src_uuid, const uuid_t *dst_uuid, int retry,
 	u32 **block, u32 *generation)
 {
 	struct tb_xdp_properties_response *res;
 	struct tb_xdp_properties req;
 	u16 data_len, len;
 	size_t total_size;
 	u32 *data = NULL;
 	int ret;

 	total_size = sizeof(*res) + TB_XDP_PROPERTIES_MAX_DATA_LENGTH * 4;
 	res = kzalloc(total_size, GFP_KERNEL);
 	if (!res)
 		return -ENOMEM;

 	memset(&req, 0, sizeof(req));
 	tb_xdp_fill_header(&req.hdr, route, retry % 4, PROPERTIES_REQUEST,
 			   sizeof(req));
 	memcpy(&req.src_uuid, src_uuid, sizeof(*src_uuid));
 	memcpy(&req.dst_uuid, dst_uuid, sizeof(*dst_uuid));

 	data_len = 0;

 	do {
 		ret = __tb_xdomain_request(ctl, &req, sizeof(req),
 					   TB_CFG_PKG_XDOMAIN_REQ, res,
 					   total_size, TB_CFG_PKG_XDOMAIN_RESP,
 					   XDOMAIN_DEFAULT_TIMEOUT);
 		if (ret)
 			goto err;

 		ret = tb_xdp_handle_error(&res->err);
 		if (ret)
 			goto err;

 		/*
 		 * Package length includes the whole payload without the
 		 * XDomain header. Validate first that the package is at
 		 * least size of the response structure.
 		 */
 		len = res->hdr.xd_hdr.length_sn & TB_XDOMAIN_LENGTH_MASK;
 		if (len < sizeof(*res) / 4) {
 			ret = -EINVAL;
 			goto err;
 		}

 		len += sizeof(res->hdr.xd_hdr) / 4;
 		len -= sizeof(*res) / 4;

 		if (res->offset != req.offset) {
 			ret = -EINVAL;
 			goto err;
 		}

 		/*
 		 * First time allocate block that has enough space for
 		 * the whole properties block.
 		 */
 		if (!data) {
 			data_len = res->data_length;
 			if (data_len > TB_XDP_PROPERTIES_MAX_LENGTH) {
 				ret = -E2BIG;
 				goto err;
 			}

 			data = kcalloc(data_len, sizeof(u32), GFP_KERNEL);
 			if (!data) {
 				ret = -ENOMEM;
 				goto err;
 			}
 		}

+		if (req.offset + len > data_len)
+			len = data_len - req.offset;
 		memcpy(data + req.offset, res->data, len * 4);
 		req.offset += len;
 	} while (!data_len || req.offset < data_len);

 	*block = data;
 	*generation = res->generation;

 	kfree(res);

 	return data_len;

 err:
 	kfree(data);
 	kfree(res);

 	return ret;
 }



